  const crossings={
    MAIN:{at:[PC.x,0],homes:[mainWest,mainEast],guards:[mainWest,mainEast],ranges:[['M3',mainWest.d,T.M3.len],['M4',0,mainEast.d]],diamond:[point('M3',T.M3.len,1,'MAIN','diamond'),point('M4',0,-1,'MAIN','diamond')]},
    BELT:{at:B.at,homes:[beltWest,beltEast],guards:[beltWest,beltEast],ranges:[['IL0',beltWest.d,beltEast.d]],diamond:[point('IL0',B.d,1,'BELT','diamond'),point('IL0',B.d,-1,'BELT','diamond')]}
  };
