  let pcFoul=0;for(let d=0;d<=T.PCX.len;d+=.5){if(ptAt('PCX',d)[0]-PC.x>13)break;pcFoul=d;}
  const corridorRanges=[['PCN',0,T.PCN.len],['PCS',0,T.PCS.len],['PCX',0,pcFoul]];
