function efRequestRoute(key,dir){const c=liveCut();if(!c)return false;const a=efChooseRequest(c,typeof key==='string'?key:null,dir);if(!a){toast('Line the route to the individual MAIN or BELT crossing first.','bad');return false;}
  if(NWT.run){EF_IL.pending={key:a.key,dir:a.dir,ids:efIds(c),pcStarted:true};toast('Hold for PC. Your request is for '+a.key+' crossing only.','bad');return false;}
  if(EF_IL.grants[a.key]){toast(a.key+' crossing already has a committed route.');return efHasGrant(a.key,c,a.dir);}
  if(Math.random()<ROUTE_CLEAR_ODDS){const ok=efRequestLocal(a.key,c,a.dir);toast(ok?a.key+' crossing only: route lined.':'Hold: equipment occupies '+a.key+' crossing.',ok?'good':'bad');return ok;}
  EF_IL.pending={key:a.key,dir:a.dir,ids:efIds(c)};const ok=efStartPC();if(ok)EF_IL.pending.pcStarted=true;toast(ok?'Hold at '+a.key+' home: PC has the through corridor.':'Hold: PC request queued until both crossings and approaches are clear.','bad');return false;
}
function efXingLabel(key,dir){return (key==='BELT'?'Industrial lead':'Main')+(dir<0?' northbound':' southbound');}
// Explicit crossing + direction (Main / Industrial lead, northbound / southbound). Does not require a lined route to the diamond, so the player can request ahead. Grants still go only through efRequestLocal / the existing PC hold rules.
function efRequestNamed(key,dir){
  const c=liveCut();if(!c){toast('Call a crew and have an engine on the road first.','bad');return false;}
  if(!EF_OPS.crossings[key]||![-1,1].includes(dir))return false;
  const label=efXingLabel(key,dir),xing=key==='BELT'?'industrial lead':'main';
  if(NWT.run){EF_IL.pending={key,dir,ids:efIds(c),pcStarted:true};toast('Hold for PC. Your request is for '+label+'.','bad');return false;}
  if(EF_IL.grants[key]){toast(label+' already has a committed route.');return efHasGrant(key,c,dir);}
  if(Math.random()<ROUTE_CLEAR_ODDS){const ok=efRequestLocal(key,c,dir);toast(ok?label+': route lined.':'Hold: equipment occupies the '+xing+' crossing.',ok?'good':'bad');return ok;}
  EF_IL.pending={key,dir,ids:efIds(c)};const ok=efStartPC();if(ok)EF_IL.pending.pcStarted=true;toast(ok?'Hold at the '+xing+' home: PC has the through corridor.':'Hold: PC request queued until both crossings and approaches are clear.','bad');return false;
}
function requestNamedRoute(key,dir){const ok=efRequestNamed(key,dir);efTowerTick();if(typeof twMenuPaint==='function')twMenuPaint(true);return ok;}
function twArt(name){return BA('tower-menu-'+name+'@2x')||BA('tower-menu-'+name)||'';}
function twUrl(name){const u=twArt(name);return u?'url("'+u+'")':'none';}
