  const p=EF_IL.pending;if(p&&!NWT.run){const c=S.cuts.find(c=>efShares(p.ids,c));if(c){if(!p.pcStarted){if(efStartPC()){p.pcStarted=true;}}else if(efRequestLocal(p.key,c,p.dir)){EF_IL.pending=null;toast('PC is clear. '+p.key+' crossing only: route lined.','good');}}}
