  const active=Object.values(EF_IL.grants).find(Boolean);S.tower=NWT.run?{st:'hold'}:active?{st:'clear',crossing:active.key,dir:active.dir>0?'S':'N'}:EF_IL.pending?{st:'waiting',crossing:EF_IL.pending.key}:null;
